'use client';
import { Clue } from '@/data/types';
export default function ClueJournal({clues,onClose}:{clues:Clue[];onClose:()=>void}) { return <div className="absolute inset-0 z-[55] flex items-center justify-center bg-black/65 p-4"><div className="panel max-h-[80%] w-full max-w-2xl overflow-auto p-5"><div className="flex justify-between"><h2 className="text-lg font-black text-yellow-200">CLUE JOURNAL</h2><button className="retro-btn px-2" onClick={onClose}>X</button></div>{clues.length===0?<p className="mt-6 text-center text-slate-400">No clues collected yet. Explore the room.</p>:<div className="mt-4 grid gap-3 md:grid-cols-2">{clues.map(c=><div key={c.id} className="border border-slate-600 bg-slate-950/70 p-3"><div className="text-xs text-cyan-300">LAYOUT {c.layout}</div><div className="font-black">{c.title}</div><p className="mt-1 text-xs text-slate-400">{c.text}</p><div className="mt-2 font-black text-yellow-200">{c.keyword}</div></div>)}</div>}</div></div>; }
